function servingsFactor(){return (settings.servings||2)/2}
function detectComponents(text){
  const found=[];
  COMPONENTS.forEach(c=>{if(c.re.test(text))found.push(c)});
  return found;
}
function proteinLine(mainText){
  const fam=mealFamily(mainText);
  const base={sea:{label:'Gambas / crustacés',unit:'g',qty:175},fish:{label:'Poisson',unit:'g',qty:170},poultry:{label:'Poulet ou dinde',unit:'g',qty:160},meat:{label:'Bœuf, veau ou porc',unit:'g',qty:160},egg:{label:'Œufs',unit:'pièce(s)',qty:2},veg:null}[fam];
  return base;
}

// ---------- Estimation nutritionnelle indicative (par personne) ----------
// Valeurs moyennes approximatives, à titre indicatif uniquement — ne remplacent pas
// une analyse nutritionnelle précise ni l'avis de votre diététicien.
const NUTRI_RATES={
  sea:{kcal:0.9,prot:0.19}, fish:{kcal:1.2,prot:0.22}, poultry:{kcal:1.5,prot:0.25},
  meat:{kcal:1.8,prot:0.26}, eggUnit:{kcal:70,prot:6},
  veggieProtein:{kcal:1.3,prot:0.15}, // tofu / tempeh / seitan / haloumi (estimation moyenne)
  starch:{kcal:1.3,prot:0.04}, veg:{kcal:0.35,prot:0.02}
};
function estimateNutrition(dishText){
  let kcal=0, prot=0;
  const fam=mealFamily(dishText);
  const isVeggieProtein=/tofu|tempeh|seitan|haloumi/i.test(dishText);
  const p=proteinLine(dishText);
  if(isVeggieProtein){
    const perPersonG=170/2; // portion type, cohérente avec les autres protéines
    kcal+=perPersonG*NUTRI_RATES.veggieProtein.kcal; prot+=perPersonG*NUTRI_RATES.veggieProtein.prot;
  } else if(p){
    if(p.unit==='pièce(s)'){
      const perPersonUnits=p.qty/2;
      kcal+=perPersonUnits*NUTRI_RATES.eggUnit.kcal; prot+=perPersonUnits*NUTRI_RATES.eggUnit.prot;
    } else {
      const perPersonG=p.qty/2;
      const r=NUTRI_RATES[fam]||NUTRI_RATES.fish;
      kcal+=perPersonG*r.kcal; prot+=perPersonG*r.prot;
    }
  }
  detectComponents(dishText).forEach(c=>{
    const perPersonQty=(c.unit==='pièce(s)')? c.qty/2 : c.qty/2;
    if(c.cat==='Féculents & légumineuses'){kcal+=perPersonQty*NUTRI_RATES.starch.kcal; prot+=perPersonQty*NUTRI_RATES.starch.prot;}
    else if(c.cat==='Légumes & fruits'){kcal+=perPersonQty*NUTRI_RATES.veg.kcal; prot+=perPersonQty*NUTRI_RATES.veg.prot;}
  });
  return {kcal:Math.round(kcal/10)*10, protein:Math.round(prot)};
}

