function setView(id){
 document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(id).classList.add('active');
 document.querySelectorAll('.bottom button').forEach(b=>b.classList.toggle('on',b.dataset.view===id));
 if(id==='favoris')renderFavorites();
 if(id==='suivi')renderResults();
 if(id==='semaine')renderWeekGrid();
}
document.querySelectorAll('.bottom button').forEach(b=>b.onclick=()=>setView(b.dataset.view));

function renderWeekGrid(){
  const week=M[i].week;
  const days=M.map((m,idx)=>({...m,idx})).filter(m=>m.week===week);
  $('weekGridTitle').textContent='Semaine '+week;
  $('weekGrid').innerHTML=days.map(d=>'<button class="weekgrid-day" data-idx="'+d.idx+'"><b>'+d.day+'</b><small>🍴 '+escHtml(cleanLunchMain(currentMeal(d.idx,'lunch')).split('+')[0].trim())+'</small><small>🌙 '+escHtml(currentMeal(d.idx,'dinner').split('+')[0].trim())+'</small></button>').join('');
  $('weekGrid').querySelectorAll('.weekgrid-day').forEach(b=>b.onclick=()=>{i=+b.dataset.idx;save();setView('menus')});
  renderBatchCooking(days);
}

// ---------- Batch cooking : regrouper les recettes de la semaine par technique ----------
function cookingMethod(dishText){
  const s=(dishText||'').toLowerCase();
  if(/carpaccio|tartare|ceviche|velouté froid|salade de|houmous/.test(s))return'🥗 Cru / assemblage';
  if(/vapeur/.test(s))return'♨️ Vapeur';
  if(/rôti|au four|papillote|croûte/.test(s))return'🔥 Four';
  if(/mariné|confit|laqué/.test(s))return'🥣 Mariné / mijoté';
  return'🍳 Poêle / grill / wok';
}
function renderBatchCooking(days){
  const groups={};
  days.forEach(d=>{
    [{label:'Déjeuner',idx:d.idx,slot:'lunch',text:cleanLunchMain(currentMeal(d.idx,'lunch'))},
     {label:'Dîner',idx:d.idx,slot:'dinner',text:currentMeal(d.idx,'dinner')}].forEach(m=>{
      const method=cookingMethod(m.text);
      groups[method]=groups[method]||[];
      groups[method].push(d.day+' — '+m.label+' : '+m.text);
    });
  });
  const order=['🔥 Four','♨️ Vapeur','🍳 Poêle / grill / wok','🥣 Mariné / mijoté','🥗 Cru / assemblage'];
  $('batchCooking').innerHTML=order.filter(k=>groups[k]).map(k=>
    '<div class="weekgrid-day"><b>'+k+'</b>'+groups[k].map(x=>'<small>'+escHtml(x)+'</small>').join('')+'</div>'
  ).join('') || '<div class="empty-card">Rien à regrouper pour le moment.</div>';
}
$('weekViewSeg') && Array.from($('weekViewSeg').children).forEach(b=>b.onclick=()=>{
  Array.from($('weekViewSeg').children).forEach(x=>x.classList.remove('on'));
  b.classList.add('on');
  const showBatch=b.dataset.view==='batch';
  $('weekGrid').style.display=showBatch?'none':'';
  $('batchCooking').style.display=showBatch?'':'none';
});

