function buildNextCycle(){
 if(M.length>BASE_M.length){i=BASE_M.length;save();setView('menus');return}
 const favLunchTexts=Object.values(favorites).filter(f=>f.slot==='lunch').map(f=>f.text);
 const favDinnerTexts=Object.values(favorites).filter(f=>f.slot==='dinner').map(f=>f.text);
 // sécurité : jamais de féculent au dîner, même via un favori
 const lunches=[...new Set([...favLunchTexts,...fullLunchPool()])];
 const dinners=[...new Set([...favDinnerTexts,...fullDinnerPool()])].filter(x=>!STARCH_RE.test(x));
 const dayNames=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];
 const extra=[];
 // historique glissant amorcé avec les 13 derniers jours du programme initial :
 // garantit qu'aucun plat ne revient à moins de 2 semaines d'intervalle
 let lunchHistory=[], dinnerHistory=[];
 for(let k=Math.max(0,BASE_M.length-13);k<BASE_M.length;k++){
   lunchHistory.push(cleanLunchMain(BASE_M[k].lunch));
   dinnerHistory.push(BASE_M[k].dinner);
 }
 function pickNoRepeat(pool,history){
   const avoid=new Set(history.slice(-13));
   const candidates=pool.filter(x=>!avoid.has(x));
   const list=candidates.length?candidates:pool; // secours si le pool filtré est vide
   return list[Math.floor(Math.random()*list.length)]; // tirage réellement aléatoire
 }
 for(let k=0;k<28;k++){
   const idx=BASE_M.length+k;
   const lunchChoice=pickNoRepeat(lunches,lunchHistory);
   const dinnerChoice=pickNoRepeat(dinners,dinnerHistory);
   lunchHistory.push(lunchChoice);dinnerHistory.push(dinnerChoice);
   const starter=ALL_STARTERS[Math.floor(Math.random()*ALL_STARTERS.length)];
   extra.push({day:dayNames[k%7],week:Math.floor(BASE_M.length/7)+1+Math.floor(k/7),lunch:'Entrée : '+starter+' • Plat : '+lunchChoice,snack:'',dinner:dinnerChoice});
 }
 M=[...BASE_M,...extra];localStorage.setItem('v6_nextcycle','1');i=BASE_M.length;save();setView('menus');
}
$('buildNextCycle').onclick=buildNextCycle;
if(localStorage.getItem('v6_nextcycle')==='1')buildNextCycle();

