// ---------- V7 : tirage aléatoire avec rotation (intègre les nouveautés dans le programme des 84 jours) ----------
// N'écrase jamais un repas déjà choisi à la main (via "Changer ce repas" / "Changer l'entrée") :
// seuls les jours encore sur leur contenu par défaut, ou déjà issus d'un tirage automatique précédent, sont retirés au sort.
// Pour que les nouveautés tropicales soient vraiment visibles (et pas juste théoriquement possibles dans
// un pool de 700+ plats), chaque semaine de 7 jours réserve un quota (2 déjeuners, 2 dîners, 2 entrées)
// tiré spécifiquement dans les nouveautés V7 ; le reste continue de tourner sur l'ensemble du programme.
// Retire une clé de la liste "issue du tirage automatique" dès que la personne la change elle-même
// (via "Changer ce repas" / "Changer l'entrée"), pour qu'un futur nouveau tirage ne l'écrase jamais.
function markManual(key){
  const s=new Set(safeGet('v7_automix_keys',[]));
  if(s.delete(key)) safeSet('v7_automix_keys',[...s]);
}
function shuffledIndices(n){const a=[...Array(n).keys()];for(let k=a.length-1;k>0;k--){const j=Math.floor(Math.random()*(k+1));[a[k],a[j]]=[a[j],a[k]];}return a;}
function automixProgram(){
  const scopeLen=Math.min(BASE_M.length, M.length);
  const allLunches=[...new Set(fullLunchPool())];
  const allDinners=[...new Set(fullDinnerPool().filter(x=>!STARCH_RE.test(x)))];
  let automixKeys=new Set(safeGet('v7_automix_keys',[]));
  const newAutomixKeys=new Set();
  const lunchHistory=[], dinnerHistory=[], starterHistory=[];
  let weekLunchFam={}, weekDinnerFam={}, curWeek=-1, forceLunchDays=new Set(), forceDinnerDays=new Set(), forceStarterDays=new Set();
  function pick(pool, recentList, famCount){
    const recent=new Set(recentList.slice(-13));
    let c=famCount? pool.filter(x=>!recent.has(x) && (famCount[mealFamily(x)]||0)<2) : pool.filter(x=>!recent.has(x));
    if(!c.length) c=pool.filter(x=>!recent.has(x));
    if(!c.length) c=pool;
    return c[Math.floor(Math.random()*c.length)];
  }
  for(let idx=0; idx<scopeLen; idx++){
    const week=Math.floor(idx/7), dayInWeek=idx%7;
    if(week!==curWeek){
      weekLunchFam={};weekDinnerFam={};curWeek=week;
      const daysLeftInWeek=Math.min(7, scopeLen-week*7);
      forceLunchDays=new Set(shuffledIndices(daysLeftInWeek).slice(0,Math.min(2,daysLeftInWeek)));
      forceDinnerDays=new Set(shuffledIndices(daysLeftInWeek).slice(0,Math.min(2,daysLeftInWeek)));
      forceStarterDays=new Set(shuffledIndices(daysLeftInWeek).slice(0,Math.min(2,daysLeftInWeek)));
    }
    const keyLunch=idx+'_lunch', keyStarter=idx+'_starter', keyDinner=idx+'_dinner';
    // Déjeuner (plat + entrée assortie)
    let lunchChoice, starterChoice;
    if(overrides[keyLunch]===undefined || automixKeys.has(keyLunch)){
      lunchChoice=forceLunchDays.has(dayInWeek)? pick(NEW_LUNCHES_V7,lunchHistory,null) : pick(allLunches,lunchHistory,weekLunchFam);
      starterChoice=forceStarterDays.has(dayInWeek)? pick(NEW_STARTERS_V7,starterHistory,null) : pick(ALL_STARTERS,starterHistory,null);
      overrides[keyLunch]='Entrée : '+starterChoice+' • Plat : '+lunchChoice;
      overrides[keyStarter]=starterChoice;
      newAutomixKeys.add(keyLunch);newAutomixKeys.add(keyStarter);
    } else {
      lunchChoice=cleanLunchMain(currentMeal(idx,'lunch'));
      starterChoice=starterForIndex(idx);
    }
    lunchHistory.push(lunchChoice);starterHistory.push(starterChoice);
    weekLunchFam[mealFamily(lunchChoice)]=(weekLunchFam[mealFamily(lunchChoice)]||0)+1;
    // Dîner
    let dinnerChoice;
    if(overrides[keyDinner]===undefined || automixKeys.has(keyDinner)){
      dinnerChoice=forceDinnerDays.has(dayInWeek)? pick(NEW_DINNERS_V7,dinnerHistory,null) : pick(allDinners,dinnerHistory,weekDinnerFam);
      overrides[keyDinner]=dinnerChoice;
      newAutomixKeys.add(keyDinner);
    } else {
      dinnerChoice=currentMeal(idx,'dinner');
    }
    dinnerHistory.push(dinnerChoice);
    weekDinnerFam[mealFamily(dinnerChoice)]=(weekDinnerFam[mealFamily(dinnerChoice)]||0)+1;
  }
  safeSet('v6_overrides',overrides);
  safeSet('v7_automix_keys',[...newAutomixKeys]);
  draw();
}
