// ---------- Wake Lock : garder l'écran allumé (pratique sur une tablette de cuisine) ----------
let wakeLock=null;
async function requestWakeLock(){
  try{
    if('wakeLock' in navigator){
      wakeLock=await navigator.wakeLock.request('screen');
      wakeLock.addEventListener('release',()=>{wakeLock=null;});
    }
  }catch(e){ /* non supporté ou refusé : on ignore silencieusement */ }
}
function releaseWakeLock(){ if(wakeLock){wakeLock.release().catch(()=>{});wakeLock=null;} }
$('keepAwakeToggle').checked=!!settings.keepAwake;
if(settings.keepAwake)requestWakeLock();
$('keepAwakeToggle').onchange=()=>{
  settings.keepAwake=$('keepAwakeToggle').checked;safeSet('v6_settings',settings);
  if(settings.keepAwake)requestWakeLock(); else releaseWakeLock();
};
document.addEventListener('visibilitychange',()=>{
  if(settings.keepAwake && document.visibilityState==='visible')requestWakeLock();
});

function applyFontScale(scale){
  document.body.classList.remove('text-large','text-xlarge');
  if(scale==='large')document.body.classList.add('text-large');
  if(scale==='xlarge')document.body.classList.add('text-xlarge');
  Array.from($('fontSizeSeg').children).forEach(b=>b.classList.toggle('on',b.dataset.scale===scale));
}
applyFontScale(settings.fontScale||'normal');
Array.from($('fontSizeSeg').children).forEach(b=>b.onclick=()=>{
  settings.fontScale=b.dataset.scale;safeSet('v6_settings',settings);applyFontScale(settings.fontScale);
});

$('exportData').onclick=()=>{
  const dump={};
  Object.keys(localStorage).forEach(k=>{if(k.startsWith('v6_')||k==='program_start_date')dump[k]=localStorage.getItem(k)});
  dump._exportedAt=new Date().toISOString();dump._version=MENUS_DATA_VERSION;
  const blob=new Blob([JSON.stringify(dump,null,2)],{type:'application/json'});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mes-menus-sauvegarde-'+new Date().toISOString().slice(0,10)+'.json';a.click();
  $('dataStatus').textContent='Export prêt au téléchargement.';
};
$('importData').onchange=e=>{
  const file=e.target.files[0];if(!file)return;
  const reader=new FileReader();
  reader.onload=()=>{
    try{
      const data=JSON.parse(reader.result);
      Object.entries(data).forEach(([k,v])=>{if(k.startsWith('_'))return;localStorage.setItem(k,v)});
      $('dataStatus').textContent='Import réussi. Rechargement…';
      setTimeout(()=>location.reload(),700);
    }catch(err){$('dataStatus').textContent='Fichier invalide.'}
  };
  reader.readAsText(file);
};

